  number,
  title,
  kind: 'narrative',
  status,
  computed_status: status === 'n/a proposed' ? 'ready' : 'missing',
  stale: false,
  reason: status === 'later' ? 'visit' : status === 'n/a proposed' ? 'Nu sunt măsurători.' : null,
  changed_input: null,
  applicability_reason: null,
  awaits: [],
